use std::{fs,path::Path,collections::BTreeSet};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/group-stack217";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);for(p,h)in read(r.join("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut ledger:BTreeSet<String>=serde_json::from_value(read("/home/ubuntu/src/zopro-perf-work/group-profile216/proof-sha256-after-main.json")).unwrap();assert_eq!(ledger.len(),59032);let mut arms=vec![];for j in read(r.join("jobs.json")).as_array().unwrap(){let arm=j["arm"].as_str().unwrap();let mut outputs=vec![];for name in[format!("audit-{arm}"),format!("verify-{arm}")]{let d=r.join("run").join(name);let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(d.join(format!("{s}.log"))),e[format!("{s}_sha256")]);}outputs.push(fs::read_to_string(d.join("stdout.log")).unwrap());}let out=&outputs[0];assert!(out.contains("exited normally"));assert!(out.contains("STACK_ENTRIES 4\n"));let summary:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["rounds"],1);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],32);assert_eq!(summary["placement_before"],summary["placement_after"]);assert_eq!(summary["boolean_routes"],if j["boolean"]==true{json!([0,1,0,0])}else{json!([0,0,0,0])});let mut rows=vec![];for l in out.lines().filter_map(|l|l.strip_prefix("STACK_ENTRY ")){let fields=l.split_whitespace().map(|s|s.split_once('=').unwrap()).collect::<std::collections::BTreeMap<_,_>>();let hex=|s:&str|u64::from_str_radix(fields[s].strip_prefix("0x").unwrap(),16).unwrap();let entry=hex("entry");let frame=hex("frame");let spill=hex("spill");let func=hex("function");assert_eq!(entry-frame,472);assert_eq!(spill-frame,240);assert_eq!(entry%16,8);assert_eq!(frame%16,0);assert_eq!(fields["n"],"30089");assert_eq!(fields["hit"].parse::<usize>().unwrap(),rows.len()+1);let base=func-0x233bb0;rows.push(json!({"hit":rows.len()+1,"entry_mod64":entry%64,"frame_mod64":frame%64,"spill_mod64":spill%64,"spill_mod32":spill%32,"spill32_crosses64":spill%64>32,"scalar_mod64":hex("scalar")%64,"return_vaddr":format!("{:x}",hex("return")-base)}));}assert_eq!(rows.len(),4);let pd=Path::new(j["proof_dir"].as_str().unwrap());assert_eq!(fs::metadata(pd.join("0.proof")).unwrap().len(),164);let proof=hash(pd.join("0.proof"));assert_eq!(hash(pd.join("0.public")),j["public_sha256"]);assert!(outputs[1].contains(&format!("VERIFIED proof_sha256={proof} ")));assert!(ledger.insert(proof.clone()));arms.push(json!({"arm":arm,"rows":rows,"proof_sha256":proof,"timings_ignored":true}));}assert_eq!(ledger.len(),59034);let p=r.join("proof-sha256-after-audit.json");assert!(!p.exists());fs::write(&p,serde_json::to_vec_pretty(&ledger).unwrap()).unwrap();let result=json!({"pass":true,"audit_only":true,"arms":arms,"SDK_calls":8,"fresh_Gnark_exports":2,"receipts":4,"stream_hashes":8,"canonical_count":ledger.len(),"canonical_sha256":hash(p),"no_performance_claim":true});fs::write(r.join("result.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");}
